//! LLM prompt module — type `#: <prompt>` + Enter and atty replaces
//! the typed line with a shell command generated by the LLM behind
//! `$LLM_API_BASE` (falls back to `$OLLAMA_HOST`).
//!
//! Default prefix is `#: ` — `#` is bash/zsh's comment character, so
//! if the module is disabled or the call fails, the original typed
//! text is at worst silently no-op'd by the shell rather than
//! executed. Configurable.
//!
//! Flow:
//!   1. User types `#: list all zig files` + Enter.
//!   2. onInput detects the prefix on the committed line, returns
//!      `Action.replace = "\x15"` — the proxy sends Ctrl+U to the
//!      shell which kills its readline buffer (the `#: …` text
//!      disappears from screen). The Enter is NOT forwarded.
//!   3. Worker thread (spawned at attach) POSTs to
//!      `${api_base}/v1/chat/completions` (OpenAI-compatible — works
//!      with Ollama via its /v1 endpoint, llama.cpp's server, vLLM,
//!      and OpenAI proper). Response JSON is parsed for
//!      `choices[0].message.content`.
//!   4. `pollShellInput` (called once per tick by the proxy) surfaces
//!      the response bytes; the proxy writes them to pty.master and
//!      readline echoes them as if the user had typed them. User
//!      reviews, edits, hits Enter to run.
//!
//! API endpoint resolution:
//!   - `$LLM_API_BASE` if set (e.g. `http://localhost:11434/v1`)
//!   - else `$OLLAMA_HOST` if set (Ollama's native env; we suffix `/v1`
//!     automatically — Ollama's native API isn't OpenAI-compatible
//!     but its `/v1/*` mirror is)
//!   - else: module is inert
//! Auth: `$LLM_API_KEY` becomes a `Bearer <key>` header if set.

const std = @import("std");
const m = @import("../module.zig");
const keymap = @import("../keymap.zig");
const Osc133 = @import("../osc133.zig").Osc133;
const parse = @import("llm/parse.zig");
const types = @import("llm/types.zig");
const dialog = @import("llm/dialog.zig");
const worker_mod_ns = @import("llm/worker.zig");
const env_mod_ns = @import("llm/env.zig");
const nowMs = @import("_lib.zig").nowMs;

extern "c" fn getenv(name: [*:0]const u8) ?[*:0]u8;

pub const Config = types.Config;

pub fn configure(comptime cfg: Config) type {
    return struct {
        pub const name = "llm";
        pub const config = cfg;

        // HTTP worker thread + request/response plumbing extracted
        // to `llm/worker.zig`. The factory call binds `cfg` into
        // the worker module's types (Shared buffer sizes,
        // effective_system_prompt comptime resolution,
        // fixture_responses path, …). Each Aliased symbol below
        // keeps the existing call sites in this file using the
        // unqualified name; tests still hit the same surface via
        // the `pub` re-exports at the bottom.
        const worker_mod = worker_mod_ns.Module(cfg);
        const effective_system_prompt = worker_mod.effective_system_prompt;

        // Env-var resolution helpers live in `llm/env.zig` — same
        // factory pattern as worker.zig / dialog.zig. Aliased so
        // the `attach` site keeps using the unqualified names.
        const env_mod = env_mod_ns.Module(cfg);
        const resolveApiBase = env_mod.resolveApiBase;
        const resolveEnv = env_mod.resolveEnv;
        const resolveContextEnv = env_mod.resolveContextEnv;
        const resolveShell = env_mod.resolveShell;

        /// Comptime-built notification for inert mode. Mentions the
        /// configured env-var names (`cfg.api_base_env` /
        /// `api_base_fallback_env`) so users who renamed them see
        /// THEIR names rather than the upstream defaults, plus a
        /// hint to use the static `Config.api_base` if they'd
        /// rather skip env-var resolution entirely.
        const inert_error_msg: []const u8 = "no endpoint set — export $" ++
            cfg.api_base_env ++ " / $" ++ cfg.api_base_fallback_env ++
            ", or set Config.api_base in config.zig";

        /// Dialog-mode system prompt. Locks the model into a strict
        /// JSON-envelope response so we can parse `action` /
        /// `command` / `description` / `reason` reliably. The
        /// instruction set is deliberately terse — every line spent
        /// on prose costs tokens that should go to the user's
        /// task.
        const effective_dialog_system_prompt: []const u8 = if (cfg.dialog_system_prompt.len > 0)
            cfg.dialog_system_prompt
        else
            \\You are an interactive shell assistant. You receive a task and step-by-step OBSERVATIONS from previously executed commands. Reply ONLY with a JSON object on a single line. Allowed shapes:
            \\{"action":"exec","command":"<single-line shell command>","description":"<one short sentence>"}
            \\{"action":"done","reason":"<one short sentence>"}
            \\{"action":"question","question":"<short question>","options":["<opt1>","<opt2>"]}
            \\Never wrap the JSON in markdown fences. Never add prose around it. The command must be a single line, runnable as-is in the user's shell.
        ;

        // RequestKind discriminator lives in worker.zig (single vs
        // dialog request body shape).
        const RequestKind = worker_mod.RequestKind;

        // Dialog-mode types live in `llm/dialog.zig` — pure enums +
        // a `Response(N)` factory. Re-exported here so existing
        // call sites keep using the unqualified names (`DialogState`,
        // `Turn`, …). The factory call resolves `cfg.max_response_bytes`
        // at comptime, giving back a Response struct sized correctly
        // for this configure() instance.
        const DialogState = dialog.State;
        const DialogAction = dialog.Action;
        const TurnKind = dialog.TurnKind;
        const Turn = dialog.Turn;
        const DialogResponse = dialog.Response(cfg.max_response_bytes);

        // Runtime-touching helpers from `llm/dialog.zig`. The factory
        // takes `Runtime` as a comptime arg because Runtime is
        // defined further down in this same `configure()` block; the
        // helpers are otherwise free of cfg-level dependencies. See
        // llm/dialog.zig's `Module()` for the body.
        const dialog_helpers = dialog.Module(cfg, Runtime);
        const pushTurn = dialog_helpers.pushTurn;
        const freeTurns = dialog_helpers.freeTurns;
        const appendCaptured = dialog_helpers.appendCaptured;
        const advancePastMarker = dialog_helpers.advancePastMarker;
        const captureConclusion = dialog_helpers.captureConclusion;
        const latchHint = dialog_helpers.latchHint;
        const latchErr = dialog_helpers.latchErr;
        const queueInjection = dialog_helpers.queueInjection;
        const dialogReset = dialog_helpers.dialogReset;
        const abortDialog = dialog_helpers.abortDialog;

        // Shared state struct (mutex + buffers shared between
        // proxy and worker thread) lives in `llm/worker.zig`.
        // Aliased so existing call sites keep using `Shared` and
        // `shared.req_buf` / `shared.res_done` / etc. unchanged.
        const Shared = worker_mod.Shared;

        pub const Runtime = struct {
            allocator: std.mem.Allocator,
            io: std.Io,
            shared: *Shared,
            /// Worker thread. `null` when the module is inert (no
            /// `$LLM_API_BASE` / `$OLLAMA_HOST` set) — saves the
            /// thread spawn for the common "module configured but
            /// no endpoint" case.
            thread: ?std.Thread,
            /// Resolved at attach. Empty = inert (no env var set).
            api_base: []u8 = &.{},
            /// Resolved at attach. Empty = no Authorization header.
            api_key: []u8 = &.{},
            /// Resolved shell name (basename of $SHELL or cfg.shell).
            shell: []u8 = &.{},
            /// Pre-built context line ("KEY=value, KEY2=value2") to
            /// append to the user message. Empty when no
            /// `context_env_vars` are configured or none of them
            /// are set in the environment. Owned by the runtime.
            context_blob: []u8 = &.{},
            /// Copy of the response surfaced via pollShellInput.
            /// Owned by the runtime; valid until the next poll.
            inject_buf: [cfg.max_response_bytes]u8 = undefined,
            inject_len: usize = 0,
            /// Latched explanation waiting to be surfaced via the
            /// next `provideHintText` call. One-shot: cleared on
            /// read so the hint row isn't re-painted forever.
            hint_buf: [512]u8 = undefined,
            hint_len: usize = 0,
            hint_pending: bool = false,
            /// Latched error-style notification waiting to be
            /// surfaced via the next `provideErrorText` call.
            /// Separate from `hint_buf` because the two slots have
            /// different styles + different precedence in the
            /// statusbar (errors win when both are active).
            err_buf: [512]u8 = undefined,
            err_len: usize = 0,
            err_pending: bool = false,
            /// Tracks whether we've already pushed the OSC 12
            /// cursor-colour change for the current prefix-typing
            /// session. Transition-driven (only emit on edge changes)
            /// so the terminal doesn't see redundant OSC traffic on
            /// every tick.
            cursor_signal_active: bool = false,
            /// True while a prompt is in flight.
            in_flight: bool = false,

            // ── AI mode state (the "explicit-actions" workflow) ──
            //
            // User types `#: ` (the prefix) → ai_mode_active flips
            // true → statusbar swaps to the AI hint → user presses
            // one of Alt+A / Alt+S / Alt+Shift+S to fire the
            // corresponding action. Enter in AI mode is swallowed
            // (no auto-fire). See `docs/llm-exec-mode-design.md`.
            ai_mode_active: bool = false,
            /// Set by `llm_exec_auto` (Alt+Shift+S). Causes the
            /// dialog handler's `.exec` arm to arm an auto-submit
            /// timer after injecting the suggested command, so the
            /// user doesn't have to press Enter for each step.
            /// Cleared by reset / cancel / `done`. Independent of
            /// `ai_mode_active`: auto-exec persists across the
            /// step-by-step dialog loop, while ai_mode_active
            /// tracks whether the user is currently TYPING a `#: …`
            /// prompt (false during the response/observation
            /// roundtrip).
            auto_mode_active: bool = false,
            /// Persistent dialog/auto MODE — stays on across multiple
            /// command cycles until the user explicitly deactivates
            /// (Esc / Ctrl+Shift+X / same-key toggle) OR the LLM
            /// emits `action=done`. While `.dialog` / `.auto`, every
            /// Enter on a non-empty line is treated as a
            /// conversational turn: the typed text is sent to the
            /// LLM as a `.user` turn AND the line still runs in the
            /// shell. This is distinct from `auto_mode_active`
            /// (which only controls the auto-submit timer for
            /// LLM-suggested commands) — they're set together when
            /// Alt+Shift+S toggles auto mode on, but `auto_mode_active`
            /// is the LOCAL flag the dialog state machine reads,
            /// while `dialog_persistent_mode` is the MACRO flag the
            /// proxy reads to decide "should this Enter become a
            /// conversational turn?".
            dialog_persistent_mode: enum { off, dialog, auto } = .off,
            /// True while waiting out the auto-submit countdown.
            /// Cleared by any user keystroke (the abort window),
            /// by the firing of the auto-submit itself, and by
            /// dialog reset / cancel / done.
            auto_exec_armed: bool = false,
            /// Monotonic ms timestamp when `auto_exec_armed` flipped
            /// to true. `onTick` fires the auto-submit when
            /// `nowMs() - auto_exec_t0_ms >= cfg.auto_delay_ms`.
            auto_exec_t0_ms: i64 = 0,
            /// Index into `cfg.models[]` for the currently-selected
            /// model. Wraps around when `Alt+M` (`llm_exec_cycle_model`)
            /// fires. Initialised to 0 at attach (first entry is
            /// the default). Stays 0 forever when `cfg.models` is
            /// empty; in that case the legacy `cfg.model` is used
            /// instead.
            current_model_idx: usize = 0,
            /// Per-call format buffer for `statusText`. Used to
            /// inject the current model name into the AI hint
            /// when `cfg.models.len > 0` — `statusText` runs every
            /// render tick, but the returned slice only needs to
            /// outlive that single call, so a stable Runtime-owned
            /// buffer is the right shape.
            ///
            /// 1 KB to fit the styled variant: the AI-mode hint
            /// embeds ~7 SGR-wrapped shortcut tokens (~33 bytes
            /// each) + a styled icon (~26 bytes) + the model name
            /// + prose. ~300 bytes total before the model name;
            /// 1 KB leaves comfortable headroom for long model
            /// names like `claude-3-5-sonnet-20241022`. Longer
            /// hints are clipped by the statusbar's own width
            /// clamp anyway.
            status_buf: [1024]u8 = undefined,
            /// Pending bytes for pollShellInput to surface. Used to
            /// route `\x15` (Ctrl+U) to the pty after onAction
            /// triggers a worker call — `onAction` can't synchronously
            /// modify the stdin path, so it queues the kill-line byte
            /// here and the next pollShellInput tick drains it
            /// AHEAD of the response. The pending injection always
            /// fits in 16 bytes (a Ctrl+U or a short ESC sequence).
            pending_injection: [16]u8 = undefined,
            pending_injection_len: usize = 0,

            // ── Dialog mode state (Alt+S) ────────────────────────
            //
            // Distinct from the single-prompt path. State machine
            // walks `idle → generating → suggesting → executing →
            // capturing_output → observation_ready → generating` in
            // a loop until the LLM says `action=done` (or the user
            // cancels). See `DialogState` for the per-state
            // semantics. Single-mode requests leave `dialog_state`
            // untouched at `.idle`.
            dialog_state: DialogState = .idle,
            /// Conversation history. Heap-allocated turns, FIFO
            /// truncation at `cfg.history_turns_max`. Freed
            /// individually as they age out, and bulk-freed on
            /// cancel / detach.
            turns: [cfg.history_turns_max]Turn = undefined,
            turns_len: usize = 0,
            /// Captured output between OSC 133 `;C` and `;D` for
            /// the most recent exec step. Filled in `onOutput`;
            /// drained in `onTick` (built into the next observation
            /// turn) and reset to 0.
            /// Heap-promoted to keep Runtime's stack footprint small —
            /// at 16 KB default this dominated the inline-Runtime size.
            /// Allocated in `attach`, freed in `detach`.
            captured_output: *[cfg.captured_output_bytes]u8,
            captured_output_len: usize = 0,
            /// True when `captured_output` was filled to the cap
            /// and tail bytes were dropped. Surfaced in the
            /// observation turn with a "[truncated]" suffix so the
            /// model knows the output was clipped.
            captured_truncated: bool = false,
            /// Per-runtime OSC 133 tracker. The proxy has its own
            /// global tracker for subprocess push/pop; we maintain
            /// a SECOND independent one here so we own the `;C` /
            /// `;D` edge stream + offsets and can capture the exact
            /// byte ranges between markers. Parsing cost is
            /// negligible — character-state-machine, no
            /// allocation.
            osc133_capture: Osc133 = undefined,
            /// Pending command suggested by the LLM, displayed at
            /// the prompt while in `.suggesting`. The user reviews,
            /// optionally edits, and presses Enter (or cancels).
            /// Lives separately from `inject_buf` because the
            /// single-mode path uses that buffer with different
            /// lifetime semantics.
            pending_command: [cfg.max_response_bytes]u8 = undefined,
            pending_command_len: usize = 0,
            /// Description of the pending command (model's
            /// `description` field). Surfaced as the hint above
            /// the bar while in `.suggesting`. 256 bytes ≈ enough
            /// for a one-line summary; longer descriptions are
            /// truncated.
            pending_description: [256]u8 = undefined,
            pending_description_len: usize = 0,
            /// Raw JSON response body for the current exec step.
            /// Owned by `pollShellInput` (where the JSON is
            /// parsed); appended verbatim as an `assistant_exec`
            /// turn so the conversation echoes back what the LLM
            /// actually emitted.
            /// Heap-promoted alongside `captured_output` — same
            /// rationale (4 KB default off the inline Runtime).
            last_assistant_json: *[cfg.max_response_bytes]u8,
            last_assistant_json_len: usize = 0,
            /// How many times we've already asked the LLM to re-do
            /// a malformed reply this dialog. Reset on dialog start
            /// and on a successful parse. Capped at
            /// `cfg.dialog_parse_retry_max` so an LLM that
            /// consistently refuses the JSON envelope can't trap
            /// the loop forever — after the cap, the dialog aborts
            /// with the same "wasn't valid JSON" error the user
            /// reported, but the user has at least had a chance
            /// for the model to self-correct.
            dialog_parse_retry_count: u8 = 0,
            /// Stored answer choices for the active question-mode
            /// turn. Populated by `handleDialogResponse` on
            /// `action=question` with `choices: [...]` JSON.
            /// Cleared on dialog reset and when the user submits
            /// their answer (free-text Enter OR ghost_pick). The
            /// `provideGhostList` hook reads from here to render
            /// the pick-list when state is
            /// `.awaiting_question_answer`.
            question_choices_storage: [dialog.max_choices][dialog.choice_max_len]u8 = undefined,
            question_choices_lens: [dialog.max_choices]usize = [_]usize{0} ** dialog.max_choices,
            question_choices_count: usize = 0,
            /// Scratch storage for the `[]const []const u8` slice
            /// `provideGhostList` returns. The slices point into
            /// `question_choices_storage`. Per-call rebuilt so
            /// callers see a stable snapshot for the duration of
            /// the hook.
            question_choices_slices: [dialog.max_choices][]const u8 = undefined,
            /// Captured conclusion text from the most recent
            /// `action=done`. Formatted as a multi-line block
            /// suitable for inline emission via the term-bytes
            /// hook (`provideTermBytes`). Persists across the
            /// dialog reset so `Alt+C` can re-emit it. Cleared
            /// only on `detach` and on a fresh `action=done`
            /// (which overwrites). Empty `conclusion_len == 0`
            /// means no completed dialog yet this session.
            conclusion_buf: [1024]u8 = undefined,
            conclusion_len: usize = 0,
            /// Latched flag — set by `handleDialogResponse` on
            /// `action=done` so the next `provideTermBytes` tick
            /// emits the conclusion banner (auto-show behaviour).
            /// Cleared after emission. The `Alt+C` action
            /// re-arms this flag for an explicit re-emit.
            conclusion_pending: bool = false,

            // ── Chat overlay (phase 2a) ──────────────────────────
            //
            // Persistent alt-screen overlay showing the LLM
            // conversation history. Alt+C toggles open/close; while
            // open, `onInput` swallows every keystroke so they don't
            // reach the shell (basic gate — full input handling
            // arrives in phase 2b). The OSC 1049 enter/exit pair is
            // emitted via `provideTermBytes`.
            //
            // Phase 2a scope: render-only — no chat input, no
            // round-trip, no auto-open. The user manually toggles
            // with Alt+C and sees the existing `turns[]` ring +
            // captured conclusion. Closes restore the underlying
            // shell screen unchanged.
            chat_overlay_open: bool = false,
            /// Set whenever the overlay needs to paint (just
            /// opened, or just closed → need to emit the exit
            /// sequence). Cleared by `provideTermBytes` after the
            /// paint bytes have been returned.
            chat_overlay_paint_pending: bool = false,
            /// Rendered overlay bytes ready for `provideTermBytes`
            /// to return. Sized for chrome + ~24 rows of conversation
            /// text + SGR styling overhead. Longer conversations
            /// truncate at the top (FIFO eviction already capped by
            /// `cfg.history_turns_max`).
            chat_overlay_buf: [4096]u8 = undefined,
            chat_overlay_buf_len: usize = 0,
        };

        pub fn attach(allocator: std.mem.Allocator, io: std.Io) !Runtime {
            const shared = try allocator.create(Shared);
            shared.* = .{};
            errdefer allocator.destroy(shared);

            // Heap-promote the two biggest inline buffers off
            // Runtime so the stack footprint stays small even with
            // generous comptime config sizes (default totals: 16 KB
            // capture + 4 KB JSON).
            const captured_output = try allocator.create([cfg.captured_output_bytes]u8);
            errdefer allocator.destroy(captured_output);
            const last_assistant_json = try allocator.create([cfg.max_response_bytes]u8);
            errdefer allocator.destroy(last_assistant_json);

            // Resolve env vars at attach time so the worker doesn't
            // have to re-read them per request.
            const api_base = try resolveApiBase(allocator);
            errdefer allocator.free(api_base);
            const api_key = try resolveEnv(allocator, cfg.api_key_env);
            errdefer allocator.free(api_key);
            const shell_name = try resolveShell(allocator);
            errdefer allocator.free(shell_name);
            const context_blob = try resolveContextEnv(allocator);
            errdefer allocator.free(context_blob);

            // Skip the worker thread entirely in inert mode. With
            // no endpoint we'll never call the worker, and onInput
            // / pollShellInput already short-circuit on
            // `api_base.len == 0`.
            const thread: ?std.Thread = if (api_base.len == 0)
                null
            else
                try std.Thread.spawn(.{}, worker, .{ shared, io, allocator, api_base, api_key, shell_name, context_blob });

            return .{
                .allocator = allocator,
                .io = io,
                .shared = shared,
                .thread = thread,
                .api_base = api_base,
                .api_key = api_key,
                .shell = shell_name,
                .context_blob = context_blob,
                .osc133_capture = Osc133.init(allocator),
                .captured_output = captured_output,
                .last_assistant_json = last_assistant_json,
            };
        }

        pub fn detach(rt: *Runtime, io: std.Io) void {
            freeTurns(rt);
            rt.osc133_capture.deinit();
            // Heap-promoted Runtime buffers are owned by the main
            // thread alone — the worker reaches into `Shared`, not
            // these — so they can be freed even on the
            // worker-still-running path that intentionally leaks
            // worker-owned state below.
            rt.allocator.destroy(rt.captured_output);
            rt.allocator.destroy(rt.last_assistant_json);
            if (rt.thread) |t| {
                {
                    rt.shared.mutex.lockUncancelable(io);
                    defer rt.shared.mutex.unlock(io);
                    rt.shared.shutdown = true;
                    rt.shared.cv.signal(io);
                }
                // Detach instead of join. The worker may be blocked
                // inside a slow HTTP request (unreachable endpoint
                // / OS TCP timeout) and won't observe `shutdown`
                // until the request returns — joining would hang
                // atty's exit for tens of seconds. The OS reaps
                // the thread when the process exits; we deliberately
                // leak the heap allocations the worker still
                // references (shared / api_base / api_key / shell /
                // context_blob) because freeing them here is a
                // use-after-free race. detach() is the documented
                // escape hatch for exactly this "fire-and-forget at
                // process exit" case.
                t.detach();
                return;
            }
            // Inert mode (no worker spawned): safe to clean up
            // synchronously.
            rt.allocator.destroy(rt.shared);
            rt.allocator.free(rt.api_base);
            rt.allocator.free(rt.api_key);
            rt.allocator.free(rt.shell);
            rt.allocator.free(rt.context_blob);
        }

        // ---- hooks --------------------------------------------------------

        pub fn onInput(rt: *Runtime, ctx: *m.Context, input: []const u8) m.Error!m.Action {
            // Chat overlay (phase 2a) — while open, every
            // non-binding keystroke is swallowed so they don't
            // reach the shell underneath the alt screen. Keymap
            // actions (Alt+C close, Esc, Ctrl+Shift+X) are
            // dispatched in the proxy BEFORE this hook, so the
            // user can still close the overlay. Phase 2b will
            // wire the swallowed bytes into a real chat-input
            // state machine instead of dropping them.
            if (rt.chat_overlay_open) return .swallow;

            // Auto-exec abort window: any keystroke during the
            // armed window disarms the pending Enter. The
            // suggested command stays on the prompt for the user
            // to edit / abort with Ctrl+Shift+X or Esc.
            if (rt.auto_exec_armed) rt.auto_exec_armed = false;

            // Observe the line state to maintain `ai_mode_active`.
            // Runs on EVERY keystroke (cheap — just a prefix
            // check). When the user types `#: ` the flag flips to
            // true; the statusText hook reads the flag and swaps
            // the bar's text to the AI mode hint. Backspacing the
            // prefix flips it back. Mode is observational only;
            // the action keys (Alt+A / Alt+S / Alt+Shift+S) are
            // what actually trigger LLM work — see `onAction`
            // below + `docs/llm-exec-mode-design.md`.
            rt.ai_mode_active = std.mem.startsWith(u8, ctx.line.current(), cfg.prefix);

            const is_enter = blk: {
                for (input) |b| if (b == 0x0D or b == 0x0A) break :blk true;
                break :blk false;
            };
            if (!is_enter) return .forward;

            // Question-answer mode: the user's typed answer is for
            // the LLM, not the shell. Replace the Enter with Ctrl+U
            // (bash kills the readline buffer; the answer never runs
            // as a command) AND commit the pre-replace line so
            // onLineCommit fires with the answer text — our
            // state-machine branch there pushes it as a `.user` turn.
            if (rt.dialog_state == .awaiting_question_answer) {
                return .{ .replace_commit = "\x15" };
            }

            // Same lookup pattern as guardrail: applyInput already
            // ran, so the line we want is in lastCommitted.
            const line = ctx.line.lastCommitted() orelse ctx.line.current();

            // Persistent dialog / auto mode: while active, every
            // Enter on a non-empty line gets sent to the LLM as a
            // `.user` turn AND runs as a shell command (the line
            // could be an LLM-suggested command that the user
            // edited, OR a free-form follow-up — in both cases we
            // want the LLM to see what was actually executed).
            //
            // Gating on the dialog state machine being IDLE here is
            // important: if we're already mid-flight (.generating,
            // .suggesting, .executing, .capturing_output,
            // .observation_ready), the LLM will get the
            // observation as the next user turn automatically via
            // OSC 133 capture — adding another `.user` turn here
            // would double-up.
            //
            // The Enter passes through to the shell (we return
            // `.forward`, not `.replace_commit`), so the typed
            // command actually runs. The dialog request fires
            // async on the worker thread; output flows back via
            // OSC 133 capture as the next observation turn.
            if (rt.dialog_persistent_mode != .off and rt.dialog_state == .idle) {
                if (line.len > 0) {
                    // Strip the optional `#: ` prefix so the user
                    // can use the same Enter-fires-LLM behaviour
                    // whether they prepend the prefix or not.
                    const body = if (std.mem.startsWith(u8, line, cfg.prefix))
                        std.mem.trim(u8, line[cfg.prefix.len..], " \t")
                    else
                        std.mem.trim(u8, line, " \t");
                    if (body.len > 0 and body.len <= cfg.max_prompt_bytes and rt.api_base.len > 0 and rt.osc133_capture.active) {
                        const initial = rt.allocator.dupe(u8, body) catch return .forward;
                        pushTurn(rt, .user, initial) catch {
                            rt.allocator.free(initial);
                            return .forward;
                        };
                        rt.auto_mode_active = (rt.dialog_persistent_mode == .auto);
                        fireDialogRequest(rt, ctx) catch |err| {
                            abortDialog(rt, ctx.io, switch (err) {
                                error.BodyTooLarge => "dialog body too large for buffer — increase Config.body_buf_bytes",
                                error.OutOfMemory => "out of memory firing dialog request",
                                else => "internal error firing dialog request",
                            });
                        };
                        // Let the Enter pass through so the command
                        // also runs in the shell. Output → OSC 133
                        // → next observation turn.
                    }
                }
                return .forward;
            }

            if (!std.mem.startsWith(u8, line, cfg.prefix)) return .forward;

            // Enter on `#: …` is configurable via `Config.enter_action`.
            // Default `.none` (no-op) — explicit action keys
            // (Alt+A / Alt+S / Alt+Shift+S) are the security gate
            // against accidental LLM calls. Users can opt back into
            // the pre-Alt-key trigger flow by setting `.single`,
            // `.dialog`, or `.auto` in their config.
            switch (cfg.enter_action) {
                .none => return .forward,
                .single => {
                    const result = triggerSinglePrompt(rt, ctx, line, .replace_commit_on_enter);
                    // Mirror the Alt+A eager-clear of
                    // `ai_mode_active`. The shell wipes the line
                    // via the returned `.replace_commit = "\x15"`,
                    // so the prefix is gone from line_state on the
                    // next keystroke. Clearing ai_mode_active now
                    // means the verbose statusbar hint disappears
                    // immediately, not on the next keypress —
                    // same flicker-free behaviour as the Alt+A
                    // path. Gated on api_base.len for the same
                    // reason: inert mode keeps the user in AI mode
                    // so they can fix config + retry.
                    if (rt.api_base.len != 0 and result == .replace_commit) {
                        rt.ai_mode_active = false;
                    }
                    return result;
                },
                .dialog, .auto => return startDialogViaEnter(rt, ctx, cfg.enter_action == .auto),
            }
        }

        /// Dispatch site for the keymap actions `llm_exec_*`. The
        /// proxy calls this for every binding match; the module
        /// gates each action on `ai_mode_active` (i.e. the user is
        /// currently inside an AI prompt — the line starts with
        /// `#: `). Outside AI mode, the actions no-op silently so
        /// stray Alt-key presses don't surprise the user.
        ///
        /// **Returns** true when the action was handled (proxy
        /// swallows the binding bytes); false when not (proxy
        /// lets the bytes flow through to readline / the inner
        /// program — so e.g. Alt+a outside AI mode still hits
        /// readline's "set-mark" or whatever the user has bound
        /// there).
        ///
        /// Per-action behaviour:
        /// - `llm_exec_single`: same as `#:<Enter>` — kick the
        ///   worker with the current line body, queue Ctrl+U for
        ///   the next `pollShellInput` tick to wipe the typed
        ///   `#: …` text. The LLM response gets injected when it
        ///   lands.
        /// - `llm_exec_dialog` / `_auto`: route through
        ///   `startDialog` — fires the multi-turn dialog request,
        ///   then waits for `;C`/`;D` markers between exec steps.
        ///   `_auto` additionally arms an auto-submit timer
        ///   (`cfg.auto_delay_ms`) so each suggested command runs
        ///   without manual Enter; any keystroke aborts the timer.
        /// - `llm_exec_cycle_model`: rotates `current_model_idx`
        ///   through `cfg.models[]`; no-op + hint when there's
        ///   only the single-model fallback.
        /// - `llm_exec_toggle_help`: latches a one-line help hint
        ///   summarising the active model / endpoint / cancel key.
        /// - `llm_exec_cancel`: clears any in-flight state, bumps
        ///   the worker's req_gen so a late response is dropped,
        ///   wipes the typed prompt via Ctrl+U injection, clears
        ///   ai_mode_active. Works outside AI mode too (drains
        ///   any leftover state).
        pub fn onAction(rt: *Runtime, ctx: *m.Context, action: keymap.Action) m.Error!bool {
            switch (action) {
                .llm_exec_single => {
                    if (!rt.ai_mode_active) return false;
                    const line = ctx.line.current();
                    const body = std.mem.trim(u8, line[cfg.prefix.len..], " \t");
                    // Empty body — user pressed Alt+A right after
                    // typing `#: ` with no task. Info hint, no
                    // worker call, no Ctrl+U; user keeps typing.
                    if (body.len == 0) {
                        latchHint(rt, "type your task after `#: ` then press Alt+A");
                        return true; // consumed (we displayed feedback)
                    }
                    // Over-length body — explicit hint instead of
                    // a silent no-op. Without this, `trigger
                    // SinglePrompt`'s internal `body.len >
                    // max_prompt_bytes` branch would return
                    // `.forward` without queuing Ctrl+U or
                    // latching feedback, and the Alt+A press
                    // would visibly do nothing.
                    if (body.len > cfg.max_prompt_bytes) {
                        latchHint(rt, "prompt too long — shorten the task and try again");
                        return true;
                    }
                    _ = triggerSinglePrompt(rt, ctx, line, .queue_pending_injection);
                    // Clear AI mode immediately — the line is
                    // about to be wiped by Ctrl+U, so the prefix
                    // won't match next time `onInput` recomputes
                    // the flag. Without this, the verbose hint
                    // would linger in the statusbar until the
                    // user's next keystroke.
                    //
                    // BUT only when the worker actually got the
                    // prompt. In inert mode (no api_base resolved
                    // at attach), `triggerSinglePrompt` latches
                    // the "no endpoint" error and returns without
                    // queuing Ctrl+U — so the typed `#: …` text
                    // stays on the prompt. If we cleared
                    // ai_mode_active here, the very next
                    // keystroke would see the prefix still on
                    // line_state.current() and flip the flag
                    // back to true, producing a visible one-
                    // tick flicker in the statusbar hint. Inert
                    // mode is the user's signal to fix their
                    // config + re-try, so leave them IN AI mode
                    // — the error notification points at the
                    // fix.
                    if (rt.api_base.len != 0) rt.ai_mode_active = false;
                    return true;
                },
                // Alt+S / Alt+Shift+S TOGGLE persistent mode rather
                // than firing a one-shot request. Mode stays on
                // across multiple command cycles until the user
                // deactivates (Esc / Ctrl+Shift+X / same-key
                // toggle) OR the LLM emits `action=done`. While in
                // mode, every Enter on a non-empty line is sent to
                // the LLM as a `.user` turn AND runs as a shell
                // command — see the Enter branch of `onInput`.
                //
                // First entry into mode ALSO fires the initial
                // request if `ai_mode_active` is true (the user
                // already typed `#: …`) — same kick-off behaviour
                // as the old action-based design. After that, the
                // user can keep typing prompts at the bare shell
                // prompt without the `#: ` prefix.
                .llm_exec_dialog => return toggleDialogMode(rt, ctx, .dialog),
                .llm_exec_auto => return toggleDialogMode(rt, ctx, .auto),
                .llm_exec_cycle_model => {
                    if (!rt.ai_mode_active) return false;
                    if (cfg.models.len == 0) {
                        // Single-model config — nothing to cycle.
                        // Honest feedback so users know why
                        // Alt+M didn't do anything.
                        latchHint(rt, "single-model config — set `models = &.{ ... }` to cycle");
                        return true;
                    }
                    rt.current_model_idx = (rt.current_model_idx + 1) % cfg.models.len;
                    // Latch a one-line hint with the new pick so
                    // the user sees confirmation. Statusbar AI
                    // hint will also reflect the new model on the
                    // next tick (statusText appends the current
                    // pick when models.len > 0).
                    const new_model = cfg.models[rt.current_model_idx];
                    var msg_buf: [128]u8 = undefined;
                    const msg = std.fmt.bufPrint(&msg_buf, "model: {s}", .{new_model}) catch new_model;
                    latchHint(rt, msg);
                    return true;
                },
                .llm_exec_toggle_help => {
                    if (!rt.ai_mode_active) return false;
                    // Help overlay — surface state that isn't in
                    // the verbose AI hint: current model + how
                    // many alternates are in the cycle, the
                    // resolved endpoint, and a pointer at the
                    // single way to actually cancel. Limited to
                    // ~256 bytes; truncates gracefully on narrow
                    // terms.
                    //
                    // BOTH cycle_info and the final message live in
                    // `buf` so the cycle slice doesn't escape a
                    // nested scope (a previous draft put cycle_info's
                    // backing array inside a `blk` expression — the
                    // slice outlived the array, classic stack-use-
                    // after-scope hazard). One outer buffer, two
                    // bufPrint calls into disjoint subslices.
                    var buf: [256]u8 = undefined;
                    const current: []const u8 = if (cfg.models.len > 0)
                        cfg.models[rt.current_model_idx]
                    else
                        cfg.model;
                    // Cycle info lives in the first 32 bytes of buf.
                    const cycle_info: []const u8 = if (cfg.models.len > 1)
                        std.fmt.bufPrint(buf[0..32], " ({d}/{d})", .{ rt.current_model_idx + 1, cfg.models.len }) catch ""
                    else
                        "";
                    const endpoint: []const u8 = if (rt.api_base.len > 0) rt.api_base else "(inert — no endpoint)";
                    // Message goes into the remaining bytes. cycle_info
                    // is referenced before its underlying storage is
                    // overwritten — bufPrint copies the formatted
                    // string verbatim, so this read-then-write order
                    // is safe.
                    const msg = std.fmt.bufPrint(buf[32..], "model: {s}{s} · endpoint: {s} · Esc cancel · Ctrl+Shift+I incognito", .{ current, cycle_info, endpoint }) catch {
                        // Truncated; render at least the model name.
                        latchHint(rt, current);
                        return true;
                    };
                    latchHint(rt, msg);
                    return true;
                },
                .llm_chat_overlay_toggle => {
                    // Phase 2a: toggle a persistent alt-screen
                    // overlay rendering the conversation history.
                    // Open shows turns + conclusion in a chrome-free
                    // text view; close exits the alt screen and
                    // restores the underlying shell. No chat input
                    // yet — that arrives in phase 2b.
                    if (!rt.chat_overlay_open) {
                        const has_content = rt.turns_len > 0 or rt.conclusion_len > 0;
                        if (!has_content) {
                            // Nothing to show yet — refuse to open
                            // (avoids an empty alt-screen that the
                            // user has to dismiss). Hint surface
                            // tells them how to populate it.
                            latchHint(rt, "no LLM session to recall — run a dialog (Alt+S) first");
                            return true;
                        }
                        rt.chat_overlay_open = true;
                        // Disarm the conclusion auto-emit latch —
                        // the overlay already renders the conclusion
                        // as content, so firing the banner again on
                        // the next tick would print the same text
                        // twice (once in the overlay, once scrolled
                        // into shell history after the overlay
                        // closes).
                        rt.conclusion_pending = false;
                    } else {
                        rt.chat_overlay_open = false;
                    }
                    rt.chat_overlay_paint_pending = true;
                    return true;
                },
                .llm_exec_cancel => {
                    // Only claim consumed when there's actual
                    // state to clear — otherwise the user's
                    // Ctrl+Shift+X bytes flow through to any
                    // inner program (vim / emacs / less) that
                    // might bind them. Without this gate every
                    // stray Ctrl+Shift+X in a normal shell got
                    // eaten by atty.
                    const dialog_active = rt.dialog_state != .idle;
                    const mode_active = rt.dialog_persistent_mode != .off;
                    const had_work = rt.in_flight or rt.ai_mode_active or rt.pending_injection_len > 0 or dialog_active or mode_active;
                    if (!had_work) return false;

                    // Dialog cancel funnels through dialogReset
                    // which handles the req_gen bump + turn
                    // cleanup + state machine reset. Always wipe
                    // the prompt — the suggested command (or
                    // `#: …` prefix) is typically visible.
                    dialogReset(rt, ctx.io);
                    queueInjection(rt, "\x15");
                    // Reset line_state to match the post-Ctrl+U
                    // shell state. The injection wipes the shell's
                    // readline buffer but `applyInput` doesn't see
                    // it (injections flow atty→shell, while
                    // line_state observes shell→user / user→shell);
                    // without this reset, line_state would keep the
                    // pre-cancel `#: …` prefix and the next Enter
                    // would re-fire the legacy single-shot
                    // trigger in `onInput`.
                    ctx.line.reset();
                    rt.ai_mode_active = false;
                    // Also exit persistent dialog/auto mode if active
                    // — the user wants out of the whole flow, not
                    // just the in-flight request.
                    rt.dialog_persistent_mode = .off;
                    rt.auto_mode_active = false;
                    return true;
                },
                else => return false, // not our action
            }
        }

        /// Trigger source — affects whether we return `.replace_commit`
        /// (the legacy `#:<Enter>` path) or queue the Ctrl+U on
        /// `pending_injection` (the `Alt+A` action path, which has no
        /// return-value channel to the proxy).
        const TriggerKind = enum { replace_commit_on_enter, queue_pending_injection };

        fn triggerSinglePrompt(
            rt: *Runtime,
            ctx: *m.Context,
            line: []const u8,
            kind: TriggerKind,
        ) m.Action {
            const body = std.mem.trim(u8, line[cfg.prefix.len..], " \t");
            if (body.len == 0 or body.len > cfg.max_prompt_bytes) return .forward;
            if (rt.api_base.len == 0) {
                // Inert mode — the user has the module configured
                // but no endpoint resolved at attach time. Latch
                // the muted-red ⚠ error notification.
                latchErr(rt, inert_error_msg);
                return .forward;
            }

            // Resolve the model INDEX to stage. Worker reads
            // `cfg.models[idx]` directly when idx is in-range, else
            // falls back to `cfg.model`. Out-of-range
            // `current_model_idx` (shouldn't happen — Alt+M wraps —
            // but defensive) clamps to 0.
            const idx_to_send: usize = if (cfg.models.len == 0)
                std.math.maxInt(usize) // sentinel: "no list, use cfg.model"
            else if (rt.current_model_idx < cfg.models.len)
                rt.current_model_idx
            else
                0;

            // Hand the prompt to the worker. Same locking + req-gen
            // bump as before — see the original onInput comment for
            // the stale-response guard rationale.
            rt.shared.mutex.lockUncancelable(ctx.io);
            defer rt.shared.mutex.unlock(ctx.io);
            @memcpy(rt.shared.req_buf[0..body.len], body);
            rt.shared.req_len = body.len;
            rt.shared.model_idx = idx_to_send;
            rt.shared.req_kind = .single;
            rt.shared.req_pending = true;
            rt.shared.req_gen +%= 1;
            rt.shared.res_done = false;
            rt.shared.res_len = 0;
            rt.shared.cv.signal(ctx.io);
            rt.in_flight = true;

            switch (kind) {
                .replace_commit_on_enter => return .{ .replace_commit = "\x15" },
                .queue_pending_injection => {
                    // onAction can't return an Action that the
                    // proxy injects. Queue the Ctrl+U on
                    // `pending_injection` so the next
                    // pollShellInput tick (~50ms) surfaces it
                    // ahead of any LLM response. Same visible
                    // effect: line gets wiped, response gets
                    // injected when ready.
                    queueInjection(rt, "\x15");
                    return .forward;
                },
            }
        }

        /// OSC 133 output capture for dialog mode. Always feeds the
        /// per-runtime tracker (so `osc133_capture.active` is current
        /// the moment the user hits Alt+S); state transitions and
        /// byte capture only fire while a dialog is mid-execution.
        ///
        /// We use a SECOND osc133 instance independent of the proxy's
        /// global one because the proxy's tracker is consumed
        /// destructively by `drainEdges()` — sharing it would race
        /// the subprocess-stack consumer.
        pub fn onOutput(rt: *Runtime, ctx: *m.Context, output: []const u8) m.Error!void {
            _ = ctx;
            rt.osc133_capture.feed(output);
            const edges = rt.osc133_capture.drainEdges();

            // Outside dialog execution, the only reason to feed was
            // to keep `active` tracking up to date. No state work
            // needed when we're idle/generating/suggesting (the
            // command hasn't run yet, so `;C` hasn't fired).
            const tracking = rt.dialog_state == .executing or rt.dialog_state == .capturing_output;
            if (!tracking) return;

            // `edgeOffset(i)` returns the byte index of the OSC
            // marker's LEADING ESC. So `output[cursor..offset]`
            // captures cleanly: everything BEFORE the marker is
            // command output; the marker bytes themselves never
            // enter the observation. After the edge fires we
            // advance `cursor` past the marker (we don't know the
            // exact terminator length here without re-parsing, so
            // we conservatively forward-scan to the first BEL or
            // ST tail and resume just past it).
            var cursor: u32 = 0;
            var capturing = rt.dialog_state == .capturing_output;
            for (edges, 0..) |edge, i| {
                const offset = rt.osc133_capture.edgeOffset(i);
                switch (edge) {
                    .cmd_start => {
                        // Stray `;C` mid-capture (no preceding `;D`):
                        // append the pre-marker bytes to the current
                        // observation BEFORE deciding the next state.
                        // We deliberately KEEP the in-progress
                        // observation across the stray marker rather
                        // than starting fresh — concatenated output is
                        // more useful to the LLM than a silently
                        // dropped half. The reset below is gated on
                        // `!capturing` for exactly this reason.
                        if (capturing and offset > cursor) {
                            appendCaptured(rt, output[cursor..@min(offset, output.len)]);
                        }
                        if (!capturing and rt.dialog_state == .executing) {
                            rt.dialog_state = .capturing_output;
                            rt.captured_output_len = 0;
                            rt.captured_truncated = false;
                            capturing = true;
                        }
                        cursor = advancePastMarker(output, offset);
                    },
                    .cmd_end, .prompt_start_implicit_end => {
                        if (capturing) {
                            if (offset > cursor) {
                                appendCaptured(rt, output[cursor..@min(offset, output.len)]);
                            }
                            capturing = false;
                            rt.dialog_state = .observation_ready;
                            // Firing the next request from onOutput
                            // would mean doing JSON serialization +
                            // mutex acquisition on the master-output
                            // hot path. Defer to `onTick` instead —
                            // ~50ms latency is fine for a dialog
                            // loop where the LLM round-trip is the
                            // dominant cost anyway.
                        }
                        cursor = advancePastMarker(output, offset);
                    },
                }
            }
            if (capturing and cursor < output.len) {
                appendCaptured(rt, output[cursor..]);
            }
        }

        /// `.observation_ready` → `.generating` transition. Triggered
        /// here (not in onOutput) so the JSON serialization and
        /// mutex acquisition stay off the master-output hot path.
        pub fn onTick(rt: *Runtime, ctx: *m.Context, elapsed_ms: u64) m.Error!void {
            _ = elapsed_ms;

            // Auto-exec: fire \r after the configured delay if
            // the user hasn't pressed any key (onInput would've
            // cleared `auto_exec_armed`). One-shot — clear the
            // flag once we enqueue the Enter so we don't re-fire
            // on the next tick.
            //
            // The injection path in proxy.zig bypasses
            // dispatchLineCommit (only stdin keystrokes pump that
            // pipeline), so the `.suggesting → .executing`
            // transition that onLineCommit would normally run
            // gets done here directly — otherwise capturing of
            // the upcoming `;C`/`;D` edges would never start and
            // the dialog would stall in .suggesting.
            if (rt.auto_exec_armed and rt.dialog_state == .suggesting) {
                const elapsed: i64 = nowMs() - rt.auto_exec_t0_ms;
                if (elapsed >= @as(i64, @intCast(cfg.auto_delay_ms))) {
                    rt.auto_exec_armed = false;
                    queueInjection(rt, "\r");
                    rt.dialog_state = .executing;
                }
            }

            if (rt.dialog_state != .observation_ready) return;

            // Push the observation as a turn, build the next
            // request, signal the worker. Any allocation failure
            // here aborts the dialog cleanly — we latch an error
            // and reset to idle so the user isn't stuck in a
            // half-state.
            const observation_slice = if (rt.captured_truncated)
                std.fmt.allocPrint(
                    rt.allocator,
                    "{s}\n[truncated — output exceeded {d} bytes]",
                    .{ rt.captured_output[0..rt.captured_output_len], cfg.captured_output_bytes },
                ) catch {
                    abortDialog(rt, ctx.io, "out of memory building observation");
                    return;
                }
            else
                rt.allocator.dupe(u8, rt.captured_output[0..rt.captured_output_len]) catch {
                    abortDialog(rt, ctx.io, "out of memory building observation");
                    return;
                };

            pushTurn(rt, .observation, observation_slice) catch {
                rt.allocator.free(observation_slice);
                abortDialog(rt, ctx.io, "out of memory recording observation");
                return;
            };
            rt.captured_output_len = 0;
            rt.captured_truncated = false;

            fireDialogRequest(rt, ctx) catch |err| {
                abortDialog(rt, ctx.io, switch (err) {
                    error.BodyTooLarge => "context too large — cancel and start a new task",
                    error.OutOfMemory => "out of memory firing follow-up request",
                    else => "internal error firing follow-up request",
                });
            };
        }

        /// Enter-key transition for dialog mode: while in
        /// `.suggesting`, the user just confirmed the suggested
        /// command — move to `.executing` so `onOutput` knows to
        /// start capturing when `;C` fires.
        ///
        /// Gated on a non-empty committed line: if the user
        /// deleted the suggestion before pressing Enter (or
        /// committed a blank line for any other reason), we'd
        /// otherwise eagerly capture the NEXT command's output as
        /// a stale observation. The reset is safer — the dialog
        /// returns to `.idle` (via dialogReset) and the user can
        /// retry from a clean state.
        pub fn onLineCommit(rt: *Runtime, ctx: *m.Context, line: []const u8) m.Error!void {
            // Question-answer path: the user typed a free-form
            // reply to the LLM's question. onInput already returned
            // `.replace_commit = "\x15"`, so bash receives Ctrl+U
            // (kills the buffer) instead of Enter — no command
            // runs. We just push the answer as the next `.user`
            // turn and fire the follow-up request.
            if (rt.dialog_state == .awaiting_question_answer) {
                const trimmed = std.mem.trim(u8, line, " \t");
                if (trimmed.len == 0) {
                    latchHint(rt, "empty answer — dialog cancelled");
                    dialogReset(rt, ctx.io);
                    rt.ai_mode_active = false;
                    return;
                }
                const answer = rt.allocator.dupe(u8, trimmed) catch {
                    abortDialog(rt, ctx.io, "out of memory recording answer");
                    return;
                };
                pushTurn(rt, .user, answer) catch {
                    rt.allocator.free(answer);
                    abortDialog(rt, ctx.io, "out of memory recording answer");
                    return;
                };
                fireDialogRequest(rt, ctx) catch |err| {
                    abortDialog(rt, ctx.io, switch (err) {
                        error.BodyTooLarge => "context too large — cancel and start a new task",
                        error.OutOfMemory => "out of memory firing follow-up request",
                        else => "internal error firing follow-up request",
                    });
                };
                return;
            }

            if (rt.dialog_state != .suggesting) return;
            const trimmed = std.mem.trim(u8, line, " \t");
            if (trimmed.len == 0) {
                latchHint(rt, "empty command — dialog cancelled, retry from scratch");
                dialogReset(rt, ctx.io);
                rt.ai_mode_active = false;
                return;
            }
            rt.dialog_state = .executing;
        }

        pub fn pollShellInput(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            // Drain `pending_injection` ahead of the worker's
            // response. Used by the `onAction` path (Alt+A) to
            // route `\x15` (Ctrl+U) to the pty so the typed
            // `#: …` is wiped — onAction has no return-value
            // channel to the proxy. One-shot; cleared on read.
            if (rt.pending_injection_len > 0) {
                const n = rt.pending_injection_len;
                @memcpy(rt.inject_buf[0..n], rt.pending_injection[0..n]);
                rt.inject_len = n;
                rt.pending_injection_len = 0;
                return rt.inject_buf[0..n];
            }

            // Inner scope so the mutex is released BEFORE we run
            // the dialog-response handler, which may re-acquire
            // the mutex in `fireDialogRequest`.
            var res_kind: RequestKind = .single;
            var n: usize = 0;
            {
                rt.shared.mutex.lockUncancelable(ctx.io);
                defer rt.shared.mutex.unlock(ctx.io);
                if (!rt.shared.res_done) return null;
                // Drop responses from a stale generation — a newer
                // prompt has already been submitted; the worker's
                // reply for THAT one is still pending. Keep
                // `in_flight = true` because the user IS waiting on
                // the newer request; clearing it would prematurely
                // remove the 🧠 thinking… status.
                if (rt.shared.res_gen != rt.shared.req_gen) {
                    rt.shared.res_done = false;
                    rt.shared.res_len = 0;
                    rt.shared.explanation_len = 0;
                    rt.shared.error_len = 0;
                    return null;
                }
                res_kind = rt.shared.res_kind;
                n = rt.shared.res_len;
                @memcpy(rt.inject_buf[0..n], rt.shared.res_buf[0..n]);
                rt.inject_len = n;

                // Latch the explanation (single mode only). Dialog
                // responses never populate `explanation_buf` — the
                // worker leaves `explanation_len = 0` for dialog
                // kind because the JSON envelope's `description`
                // field is surfaced later (inside
                // `handleDialogResponse` via `latchHint`). The
                // shared `explanation_buf` is therefore dead weight
                // on the dialog path; kept around so single-mode
                // doesn't have to branch.
                const exp_n = rt.shared.explanation_len;
                if (n > 0 and exp_n > 0) {
                    @memcpy(rt.hint_buf[0..exp_n], rt.shared.explanation_buf[0..exp_n]);
                    rt.hint_len = exp_n;
                    rt.hint_pending = true;
                }

                // Failure path: nothing to inject, but the worker
                // may have latched a diagnostic. Surface it via the
                // *error* slot (not the hint slot) so it renders
                // in muted red with the ⚠ glyph.
                const err_n = rt.shared.error_len;
                if (n == 0 and err_n > 0) {
                    const copy_n = @min(err_n, rt.err_buf.len);
                    @memcpy(rt.err_buf[0..copy_n], rt.shared.error_buf[0..copy_n]);
                    rt.err_len = copy_n;
                    rt.err_pending = true;
                }

                rt.shared.res_done = false;
                rt.shared.res_len = 0;
                rt.shared.explanation_len = 0;
                rt.shared.error_len = 0;
            }
            rt.in_flight = false;

            // Dialog mode: parse the JSON envelope on the main
            // thread (where the runtime + state machine live) and
            // act on the LLM's instruction. Returns the bytes to
            // inject (the suggested command for `action=exec`) or
            // null for done/error/question paths.
            //
            // The `inject_buf` was populated with the raw JSON
            // envelope above by the shared-state copy — that's
            // the wrong thing to expose if any downstream caller
            // reads `rt.inject_buf[0..rt.inject_len]` directly
            // assuming it holds the next-injection bytes. Zero
            // `inject_len` now so any such stale read sees an
            // empty slice instead of JSON; the returned slice
            // from `handleDialogResponse` is the authoritative
            // injection payload for dialog mode.
            if (res_kind == .dialog) {
                rt.inject_len = 0;
                return try handleDialogResponse(rt, ctx, n);
            }

            // Single mode: n == 0 → worker signalled failure
            // (network error, non-2xx, parse failure). Nothing to
            // inject; the statusbar already cleared via
            // `in_flight = false`. The error hint above is what
            // the user will see.
            if (n == 0) return null;
            // Stage the line's author for the next submit() so
            // downstream consumers (atuin's --author tag,
            // guardrail's author-aware rules) see `.llm` instead
            // of the default `.user`. The flag persists in
            // line_state until submit() snapshots it; backspace /
            // killLine / killWord that empty the buffer reset it,
            // so a user who wipes and retypes still commits as
            // `.user`.
            ctx.line.setCommitAuthor(.llm);
            return rt.inject_buf[0..rt.inject_len];
        }

        /// Process a parsed dialog response. Branches by `action`:
        /// `exec` injects the command + transitions to `.suggesting`
        /// (description goes to the hint row, auto-exec arms if
        /// the user picked Alt+Shift+S); `done` clears state and
        /// latches a confirmation; `question` latches the prompt
        /// text and transitions to `.awaiting_question_answer` so
        /// the next typed line becomes the next `.user` turn (see
        /// onInput's `.replace_commit` redirect that keeps bash
        /// from executing the answer). Returns bytes to inject —
        /// for `exec` that's the command; for done/question/error
        /// it's null.
        fn handleDialogResponse(rt: *Runtime, ctx: *m.Context, n: usize) m.Error!?[]const u8 {
            if (n == 0) {
                // Worker reported failure; the error slot already
                // has the diagnostic. End the dialog cleanly.
                dialogReset(rt, ctx.io);
                rt.ai_mode_active = false;
                queueInjection(rt, "\x15");
                return null;
            }

            const raw = rt.inject_buf[0..n];

            // Stash the raw response so it becomes the next
            // assistant_exec turn. Done before parsing so we have
            // it whether or not the JSON parses cleanly.
            const stash_n = @min(raw.len, rt.last_assistant_json.len);
            @memcpy(rt.last_assistant_json[0..stash_n], raw[0..stash_n]);
            rt.last_assistant_json_len = stash_n;

            var parsed: DialogResponse = .{};
            parseDialogResponse(rt.allocator, raw, &parsed) catch {
                // Self-correction loop — give the model a chance to
                // re-emit a valid JSON envelope. Cap at
                // `cfg.dialog_parse_retry_max` so a model that
                // refuses the format can't trap the loop. The
                // bad reply itself is pushed as the assistant turn
                // (so the model sees its own output), then a user
                // turn explains the parse failure in concrete
                // terms ("you replied X, here's what was wrong,
                // please re-emit JSON exactly like this …").
                if (rt.dialog_parse_retry_count < cfg.dialog_parse_retry_max) {
                    rt.dialog_parse_retry_count += 1;
                    requestParseRetry(rt, ctx, "wasn't valid JSON") catch {
                        latchErr(rt, "LLM reply wasn't valid JSON — cancel and retry");
                        dialogReset(rt, ctx.io);
                        rt.ai_mode_active = false;
                        queueInjection(rt, "\x15");
                    };
                    return null;
                }
                latchErr(rt, "LLM reply wasn't valid JSON (gave up after retries) — cancel and re-prompt");
                dialogReset(rt, ctx.io);
                rt.ai_mode_active = false;
                queueInjection(rt, "\x15");
                return null;
            };
            // Successful parse — reset the retry counter so any
            // future malformed reply within this dialog gets the
            // full retry budget again.
            rt.dialog_parse_retry_count = 0;

            switch (parsed.action) {
                .exec => {
                    if (parsed.command_len == 0) {
                        // Same retry budget as the JSON-parse-fail
                        // path — an action=exec without a `command`
                        // field is a model error of the same shape
                        // (envelope is technically valid JSON but
                        // doesn't satisfy our protocol contract).
                        if (rt.dialog_parse_retry_count < cfg.dialog_parse_retry_max) {
                            rt.dialog_parse_retry_count += 1;
                            requestParseRetry(rt, ctx, "had action=exec but no command field") catch {
                                latchErr(rt, "LLM reply had no command — cancel and retry");
                                dialogReset(rt, ctx.io);
                                rt.ai_mode_active = false;
                                queueInjection(rt, "\x15");
                            };
                            return null;
                        }
                        latchErr(rt, "LLM reply had no command (gave up after retries) — cancel and re-prompt");
                        dialogReset(rt, ctx.io);
                        rt.ai_mode_active = false;
                        queueInjection(rt, "\x15");
                        return null;
                    }
                    // Echo the assistant's JSON back to the model
                    // on the next turn so the conversation stays
                    // coherent.
                    const assistant_copy = rt.allocator.dupe(u8, rt.last_assistant_json[0..rt.last_assistant_json_len]) catch {
                        abortDialog(rt, ctx.io, "out of memory continuing dialog");
                        return null;
                    };
                    pushTurn(rt, .assistant_exec, assistant_copy) catch {
                        rt.allocator.free(assistant_copy);
                        abortDialog(rt, ctx.io, "out of memory continuing dialog");
                        return null;
                    };

                    // Stage the command for injection. Cap +
                    // copy in case the LLM's command exceeds
                    // `cfg.max_response_bytes` (shouldn't — the
                    // command field is bounded at parse time —
                    // but defensive).
                    const cmd = parsed.command();
                    const cmd_n = @min(cmd.len, rt.pending_command.len);
                    @memcpy(rt.pending_command[0..cmd_n], cmd[0..cmd_n]);
                    rt.pending_command_len = cmd_n;

                    if (parsed.description_len > 0) {
                        const desc = parsed.description();
                        const desc_n = @min(desc.len, rt.pending_description.len);
                        @memcpy(rt.pending_description[0..desc_n], desc[0..desc_n]);
                        rt.pending_description_len = desc_n;
                        latchHint(rt, desc);
                    }

                    rt.dialog_state = .suggesting;
                    // Same author-staging contract as single mode —
                    // see the matching call in `pollShellInput`.
                    ctx.line.setCommitAuthor(.llm);
                    // Stage the LLM's description as the intent so
                    // downstream modules (atuin's `--intent` flag)
                    // can persist "user asked for X" alongside the
                    // command in history. Empty when the LLM didn't
                    // emit a description (already handled by
                    // line_state's len==0 short-circuit on read).
                    if (rt.pending_description_len > 0) {
                        ctx.line.setCommitIntent(rt.pending_description[0..rt.pending_description_len]);
                    }
                    // Arm the auto-submit timer if we're in
                    // auto-exec mode (Alt+Shift+S). onTick fires
                    // the Enter after cfg.auto_delay_ms; any user
                    // keystroke (via onInput) disarms it.
                    if (rt.auto_mode_active) {
                        rt.auto_exec_armed = true;
                        rt.auto_exec_t0_ms = nowMs();
                    }
                    // Return the command bytes for injection at
                    // the shell prompt — directly from
                    // `pending_command` so the buffer's role stays
                    // obvious (no second purpose-shifted reuse of
                    // `inject_buf`, which the single-mode path
                    // owns with different lifetime semantics).
                    return rt.pending_command[0..rt.pending_command_len];
                },
                .done => {
                    // Tally the conversation so the user gets a
                    // glance-able summary of what just happened —
                    // useful both for the loop they just exited
                    // AND as a quick sanity check ("did the model
                    // really execute 12 commands or am I
                    // misremembering?"). Counts are pre-reset
                    // since `dialogReset` below clears `turns_len`.
                    var exec_count: usize = 0;
                    var observation_count: usize = 0;
                    var user_count: usize = 0;
                    for (rt.turns[0..rt.turns_len]) |t| switch (t.kind) {
                        .assistant_exec => exec_count += 1,
                        .observation => observation_count += 1,
                        .user => user_count += 1,
                    };
                    // Sized for: "✓ done — " (~12) + reason (≤256) +
                    // " · N execs / N obs / N turns" (~40). 384B
                    // leaves comfortable headroom for the formatted
                    // suffix even at max reason length.
                    var msg_buf: [384]u8 = undefined;
                    const reason = parsed.reason();
                    const msg = if (reason.len > 0)
                        std.fmt.bufPrint(&msg_buf, "✓ done — {s} · {d} execs / {d} obs / {d} turns", .{ reason, exec_count, observation_count, user_count }) catch
                            (std.fmt.bufPrint(&msg_buf, "✓ done — {s}", .{reason}) catch "✓ done")
                    else
                        std.fmt.bufPrint(&msg_buf, "✓ done · {d} execs / {d} obs / {d} turns", .{ exec_count, observation_count, user_count }) catch "✓ done";
                    latchHint(rt, msg);
                    // Capture the conclusion banner BEFORE dialogReset
                    // wipes `turns_len`. Banner is multi-line ANSI
                    // text suitable for inline emission via
                    // `provideTermBytes` — scrolls into the
                    // shell's normal history above the next prompt,
                    // re-emittable via Alt+C
                    // (`llm_chat_overlay_toggle`). See `captureConclusion`.
                    captureConclusion(rt, reason, exec_count, observation_count, user_count);
                    // Order matters: dialogReset clears the pending
                    // flag (so a cancel between a stale `.done` and
                    // the next term-bytes tick doesn't fire the
                    // banner spuriously). Arm AFTER the reset.
                    dialogReset(rt, ctx.io);
                    rt.conclusion_pending = true;
                    rt.ai_mode_active = false;
                    // LLM signalling done also deactivates the
                    // persistent mode — user can re-enter via
                    // Alt+S / Alt+Shift+S if they want another
                    // session.
                    rt.dialog_persistent_mode = .off;
                    rt.auto_mode_active = false;
                    return null;
                },
                .question => {
                    // Latch the prompt so the user sees what's
                    // being asked, transition to a wait state, and
                    // surface AI mode so the user's free-form reply
                    // becomes the next `.user` turn (via
                    // onLineCommit / fireDialogRequest). Auto-exec
                    // disarms — the answer is the user's, not the
                    // LLM's, so no auto-submit timer.
                    const q = parsed.question();
                    // Multi-choice: copy choices into Runtime-
                    // owned storage so they outlive `parsed`. The
                    // `provideGhostList` hook reads from here when
                    // the state machine is awaiting an answer.
                    rt.question_choices_count = parsed.choices_count;
                    for (0..parsed.choices_count) |i| {
                        const choice = parsed.choice(i);
                        const copy_len = @min(choice.len, rt.question_choices_storage[i].len);
                        @memcpy(rt.question_choices_storage[i][0..copy_len], choice[0..copy_len]);
                        rt.question_choices_lens[i] = copy_len;
                    }
                    if (q.len > 0) {
                        // When choices are present, append a
                        // discoverable footer hint so users know
                        // they can use Ctrl+1..9 to pick.
                        if (parsed.choices_count > 0) {
                            var msg_buf: [512]u8 = undefined;
                            const msg = std.fmt.bufPrint(&msg_buf, "{s} — Ctrl+1..{d} to pick, or type", .{ q, parsed.choices_count }) catch q;
                            latchHint(rt, msg);
                        } else {
                            latchHint(rt, q);
                        }
                    } else {
                        latchHint(rt, "LLM asked a question without text — answer or cancel.");
                    }
                    rt.dialog_state = .awaiting_question_answer;
                    rt.auto_exec_armed = false;
                    rt.ai_mode_active = true;
                    return null;
                },
            }
        }

        /// Latch the OSC-133-gate diagnostic error. Surfaces the
        /// cumulative byte-feed + dispatch counts so the user can
        /// tell at a glance WHY the gate is closed:
        ///
        ///   - `bytes=0` → atty's `onOutput` was never called. The
        ///     LLM module isn't seeing shell output at all (very
        ///     unlikely — would mean a broken dispatcher wiring).
        ///   - `bytes>0 dispatches=0` → shell IS emitting output but
        ///     no OSC 133 markers among it. Either the init snippet
        ///     never ran, the user's .bashrc overwrote
        ///     `PROMPT_COMMAND` after the eval, or the user is in a
        ///     shell other than bash with the bash init.
        ///   - `bytes>0 dispatches>0 but active=false` → impossible
        ///     by construction (dispatchOsc sets active before
        ///     incrementing the counter); kept defensively in case
        ///     the parser ever changes shape.
        fn latchOsc133Diag(rt: *Runtime) void {
            const fed = rt.osc133_capture.total_bytes_fed;
            const dispatches = rt.osc133_capture.total_dispatches;
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(
                &buf,
                "exec mode needs OSC 133 (bytes={d} dispatches={d}) — run `eval \"$(atty init bash)\"` or use Alt+A",
                .{ fed, dispatches },
            ) catch "exec mode needs OSC 133 — run `eval \"$(atty init bash)\"` or use Alt+A";
            latchErr(rt, msg);
        }

        /// Same effect as `startDialog`, but returns `m.Action` so
        /// the `onInput` Enter branch can wipe the prompt via
        /// `.replace_commit = "\x15"` (the shell never sees the
        /// Enter or the `#: …` text). Returns `.forward` for the
        /// gate-failed cases — the gate failures latch a hint or
        /// error notification, so the user still gets feedback, but
        /// the Enter falls through to bash which treats `#: …` as a
        /// comment (no-op). Mirrors `startDialog` byte-for-byte
        /// except for the replace-via-Enter wiring at the success
        /// site.
        fn startDialogViaEnter(rt: *Runtime, ctx: *m.Context, auto: bool) m.Action {
            if (!rt.ai_mode_active) return .forward;
            const line = ctx.line.current();
            const body = std.mem.trim(u8, line[cfg.prefix.len..], " \t");
            if (body.len == 0) {
                latchHint(rt, if (auto)
                    "type your task after `#: ` then press Enter"
                else
                    "type your task after `#: ` then press Enter");
                return .forward;
            }
            if (body.len > cfg.max_prompt_bytes) {
                latchHint(rt, "prompt too long — shorten the task and try again");
                return .forward;
            }
            if (rt.api_base.len == 0) {
                latchErr(rt, inert_error_msg);
                return .forward;
            }
            if (!rt.osc133_capture.active) {
                latchOsc133Diag(rt);
                return .forward;
            }
            const initial = rt.allocator.dupe(u8, body) catch {
                latchErr(rt, "out of memory starting dialog");
                return .forward;
            };
            pushTurn(rt, .user, initial) catch {
                rt.allocator.free(initial);
                latchErr(rt, "out of memory starting dialog");
                return .forward;
            };
            rt.auto_mode_active = auto;
            fireDialogRequest(rt, ctx) catch |err| {
                abortDialog(rt, ctx.io, switch (err) {
                    error.BodyTooLarge => "dialog body too large for buffer — increase Config.body_buf_bytes",
                    error.OutOfMemory => "out of memory firing dialog request",
                    else => "internal error firing dialog request",
                });
                return .forward;
            };
            rt.ai_mode_active = false;
            return .{ .replace_commit = "\x15" };
        }

        /// Toggle persistent dialog/auto mode.
        ///
        ///   - off → target mode: activate. If `ai_mode_active`
        ///     (user typed `#: …`), ALSO fire the initial dialog
        ///     request immediately so the first prompt round-trips.
        ///   - same as target mode: deactivate. Clear mode flag
        ///     and reset any in-flight dialog state.
        ///   - other mode → target mode: switch. Update mode flag
        ///     without disrupting an in-flight cycle (so the user
        ///     can switch from dialog ↔ auto mid-loop without
        ///     losing context — the next `.exec` step will respect
        ///     the new mode's auto-submit setting).
        ///
        /// Returns true always (action consumed — the user will see
        /// the statusbar / cursor indicator flip even if no
        /// request fires).
        fn toggleDialogMode(rt: *Runtime, ctx: *m.Context, target: @TypeOf(rt.dialog_persistent_mode)) bool {
            const current = rt.dialog_persistent_mode;
            if (current == target) {
                // Deactivate: clear mode + reset any in-flight
                // state. Uses the same path as `llm_exec_cancel` so
                // the worker's req_gen bumps + turn cleanup happen
                // consistently.
                rt.dialog_persistent_mode = .off;
                rt.auto_mode_active = false;
                if (rt.dialog_state != .idle or rt.in_flight) {
                    dialogReset(rt, ctx.io);
                    queueInjection(rt, "\x15");
                    ctx.line.reset();
                    rt.ai_mode_active = false;
                }
                latchHint(rt, switch (current) {
                    .off => unreachable,
                    .dialog => "dialog mode OFF",
                    .auto => "auto mode OFF",
                });
                return true;
            }
            // Activate (from .off) or switch (from other mode).
            const switching = current != .off;
            rt.dialog_persistent_mode = target;
            rt.auto_mode_active = (target == .auto);
            if (switching) {
                latchHint(rt, switch (target) {
                    .off => unreachable,
                    .dialog => "→ dialog mode",
                    .auto => "→ auto mode",
                });
                return true;
            }
            // First-time entry into mode: kick off the initial
            // request if the user already typed a `#: …` prompt.
            // Otherwise just announce the mode and wait for the
            // next Enter to fire a request from a free-form line.
            if (rt.ai_mode_active) {
                return startDialog(rt, ctx, target == .auto);
            }
            latchHint(rt, switch (target) {
                .off => unreachable,
                .dialog => "dialog mode ON — type a task and press Enter",
                .auto => "auto mode ON — type a task and press Enter",
            });
            return true;
        }

        fn startDialog(rt: *Runtime, ctx: *m.Context, auto: bool) bool {
            if (!rt.ai_mode_active) return false;
            const line = ctx.line.current();
            const body = std.mem.trim(u8, line[cfg.prefix.len..], " \t");
            if (body.len == 0) {
                latchHint(rt, if (auto)
                    "type your task after `#: ` then press Alt+Shift+S"
                else
                    "type your task after `#: ` then press Alt+S");
                return true;
            }
            if (body.len > cfg.max_prompt_bytes) {
                latchHint(rt, "prompt too long — shorten the task and try again");
                return true;
            }
            if (rt.api_base.len == 0) {
                latchErr(rt, inert_error_msg);
                return true;
            }
            // Dialog mode (both flavours) requires OSC 133 — without
            // `;C` / `;D` we can't tell when the shell finished
            // running each step's command. Single mode (Alt+A)
            // doesn't have this requirement.
            if (!rt.osc133_capture.active) {
                latchOsc133Diag(rt);
                return true;
            }
            const initial = rt.allocator.dupe(u8, body) catch {
                latchErr(rt, "out of memory starting dialog");
                return true;
            };
            pushTurn(rt, .user, initial) catch {
                rt.allocator.free(initial);
                latchErr(rt, "out of memory starting dialog");
                return true;
            };
            rt.auto_mode_active = auto;
            fireDialogRequest(rt, ctx) catch |err| {
                abortDialog(rt, ctx.io, switch (err) {
                    error.BodyTooLarge => "dialog body too large for buffer — increase Config.body_buf_bytes",
                    error.OutOfMemory => "out of memory firing dialog request",
                    else => "internal error firing dialog request",
                });
                return true;
            };
            queueInjection(rt, "\x15");
            rt.ai_mode_active = false;
            return true;
        }

        /// exceeds `cfg.body_buf_bytes` (the conversation has
        /// outgrown the shared buffer — user needs to cancel).
        fn fireDialogRequest(rt: *Runtime, ctx: *m.Context) !void {
            const model_for_request: []const u8 = if (rt.current_model_idx < cfg.models.len)
                cfg.models[rt.current_model_idx]
            else
                cfg.model;

            // Build the JSON body OUTSIDE the mutex (allocator work,
            // potentially expensive). In fixture mode the worker
            // discards the body entirely, so skip the serialization
            // altogether.
            const built_body: ?[]u8 = if (cfg.fixture_responses.len > 0) null else blk: {
                const body = try buildDialogRequestBody(
                    rt.allocator,
                    model_for_request,
                    effective_dialog_system_prompt,
                    rt.shell,
                    rt.context_blob,
                    rt.turns[0..rt.turns_len],
                );
                if (body.len > cfg.body_buf_bytes) {
                    rt.allocator.free(body);
                    return error.BodyTooLarge;
                }
                break :blk body;
            };
            defer if (built_body) |b| rt.allocator.free(b);

            const idx_to_send: usize = if (cfg.models.len == 0)
                std.math.maxInt(usize)
            else if (rt.current_model_idx < cfg.models.len)
                rt.current_model_idx
            else
                0;

            // SINGLE critical section: body copy + metadata stamp
            // happen under one lock so the worker never sees a half-
            // written request (e.g. fresh body bytes with stale
            // `body_len`). Mirrors the single-mode trigger path's
            // copy-and-stamp-together shape.
            rt.shared.mutex.lockUncancelable(ctx.io);
            defer rt.shared.mutex.unlock(ctx.io);
            if (built_body) |b| {
                @memcpy(rt.shared.body_buf[0..b.len], b);
                rt.shared.body_len = b.len;
            } else {
                rt.shared.body_len = 0;
            }
            rt.shared.model_idx = idx_to_send;
            rt.shared.req_kind = .dialog;
            rt.shared.req_pending = true;
            rt.shared.req_gen +%= 1;
            rt.shared.res_done = false;
            rt.shared.res_len = 0;
            rt.shared.cv.signal(ctx.io);
            rt.in_flight = true;
            rt.dialog_state = .generating;
        }

        /// Echo the LLM's malformed reply back as an `assistant_exec`
        /// turn AND push a corrective user turn explaining what was
        /// wrong, then fire the dialog request again. Used by the
        /// parse-fail and missing-field branches of
        /// `handleDialogResponse` to give the model a chance to
        /// self-correct.
        ///
        /// `reason` is a short human-readable description of the
        /// failure ("wasn't valid JSON", "had action=exec but no
        /// command field", …) that gets formatted into the
        /// corrective prompt. Caller's responsibility to gate on
        /// retry budget; this function unconditionally fires the
        /// retry.
        fn requestParseRetry(rt: *Runtime, ctx: *m.Context, reason: []const u8) !void {
            // Echo the malformed reply back as an assistant turn so
            // the model sees its own output in context. Without
            // this the corrective user turn would seem to come
            // from nowhere.
            const bad_reply = rt.last_assistant_json[0..rt.last_assistant_json_len];
            const assistant_copy = try rt.allocator.dupe(u8, bad_reply);
            errdefer rt.allocator.free(assistant_copy);
            try pushTurn(rt, .assistant_exec, assistant_copy);

            // Build the corrective user turn. Kept short — most
            // models react better to a terse correction than a
            // wall of meta-commentary.
            const corrective = try std.fmt.allocPrint(
                rt.allocator,
                "Your previous reply {s}. Reply STRICTLY with JSON: " ++
                    "{{\"action\":\"exec\",\"command\":\"…\",\"description\":\"…\"}} " ++
                    "or {{\"action\":\"done\",\"reason\":\"…\"}} " ++
                    "or {{\"action\":\"question\",\"question\":\"…\"}}. " ++
                    "No prose. No markdown fences. No code blocks.",
                .{reason},
            );
            errdefer rt.allocator.free(corrective);
            try pushTurn(rt, .user, corrective);

            // Fire the retry. fireDialogRequest builds the request
            // body from the full turn list (including our newly
            // appended assistant + corrective turns), bumps
            // req_gen, signals the worker. Dialog state transitions
            // through .generating → .suggesting on the next response.
            try fireDialogRequest(rt, ctx);

            // Surface the retry visibly so the user knows
            // something's happening (the loop isn't silent).
            var msg_buf: [128]u8 = undefined;
            const msg = std.fmt.bufPrint(
                &msg_buf,
                "LLM reply {s} — retrying ({d}/{d})",
                .{ reason, rt.dialog_parse_retry_count, cfg.dialog_parse_retry_max },
            ) catch "LLM reply malformed — retrying";
            latchHint(rt, msg);
        }

        /// One-shot hint surface: returns the latched explanation
        /// the first time it's called after a fresh response, then
        /// returns null until the next response arrives. Cleared
        /// on read so the hint row's TTL governs how long the
        /// text stays visible — the module doesn't keep
        /// re-painting.
        pub fn provideHintText(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            _ = ctx;
            if (!rt.hint_pending) return null;
            rt.hint_pending = false;
            return rt.hint_buf[0..rt.hint_len];
        }

        /// Multi-choice answer pick-list. Active when the LLM
        /// emitted `action=question` with a `choices: [...]` array
        /// — atty renders the choices via the same ghost_list path
        /// atuin uses, and `Ctrl+1..9` / `Esc+1..9` substitutes the
        /// picked choice text into the prompt. The user then
        /// presses Enter to submit (existing `awaiting_question_answer`
        /// path treats Enter as the answer turn).
        ///
        /// Returns null when:
        ///   - State isn't `.awaiting_question_answer`.
        ///   - Question was emitted without a `choices` array
        ///     (free-text answer expected).
        ///   - The user already started typing a free-text reply
        ///     (line non-empty) — the choices would shadow atuin's
        ///     history matches otherwise; we yield priority back.
        pub fn provideGhostList(rt: *Runtime, ctx: *m.Context) m.Error!?[]const []const u8 {
            if (rt.dialog_state != .awaiting_question_answer) return null;
            if (rt.question_choices_count == 0) return null;
            const line = ctx.line.current();
            if (line.len > 0) return null;
            for (0..rt.question_choices_count) |i| {
                rt.question_choices_slices[i] = rt.question_choices_storage[i][0..rt.question_choices_lens[i]];
            }
            return rt.question_choices_slices[0..rt.question_choices_count];
        }

        /// Sibling of `provideHintText` — surfaces a latched error
        /// notification (muted-red row above the status bar). Same
        /// one-shot semantics as `provideHintText`.
        pub fn provideErrorText(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            _ = ctx;
            if (!rt.err_pending) return null;
            rt.err_pending = false;
            return rt.err_buf[0..rt.err_len];
        }

        // Comptime SGR escape constants for the AI-mode statusbar
        // hint. The bar wraps the whole segment in `dim` (default
        // bar style); these inline escapes cancel dim around the
        // colored span and re-apply it after, so prose between
        // styled spans stays dim.
        //
        // Each open/close is a single combined CSI (`\x1B[a;b;cm`)
        // rather than three separate ones — saves ~6 bytes per
        // styled token, which matters because the statusbar's
        // line budget is finite and the hint embeds 7+ tokens.
        //
        // CSI 22 = normal intensity (cancels dim AND bold).
        // CSI 39 = default foreground.
        //
        // When the color is null, the corresponding wrap is empty
        // — segments inherit the bar's dim styling (legacy look).
        const icon_open: []const u8 = if (cfg.statusbar_icon_color) |c|
            std.fmt.comptimePrint("\x1B[22;38;5;{d}m", .{c})
        else
            "";
        const icon_close: []const u8 = if (cfg.statusbar_icon_color != null)
            "\x1B[39;2m"
        else
            "";
        const key_open: []const u8 = if (cfg.statusbar_shortcut_color) |c|
            std.fmt.comptimePrint("\x1B[22;1;38;5;{d}m", .{c})
        else
            "";
        const key_close: []const u8 = if (cfg.statusbar_shortcut_color != null)
            "\x1B[22;39;2m"
        else
            "";

        // Helper to wrap a shortcut token comptime so the assembled
        // hint string stays a const where possible.
        const Wrap = struct {
            fn key(comptime label: []const u8) []const u8 {
                return key_open ++ label ++ key_close;
            }
            fn icon(comptime glyph: []const u8) []const u8 {
                return icon_open ++ glyph ++ icon_close;
            }
        };

        // Pre-built status strings for the persistent dialog/auto
        // mode views. Comptime concatenation so the assembled
        // bytes are static — no per-tick formatting cost. The
        // shortcut tokens (Esc / Ctrl+Shift+X) are styled the same
        // as Alt+A / Alt+S in AI mode so visual vocabulary is
        // consistent across all status views.
        const ai_idle_hint = Wrap.icon("\u{2728}") ++ " AI \u{00B7} " ++
            Wrap.key("Alt+A") ++ " single \u{00B7} " ++
            Wrap.key("Alt+S") ++ " dialog \u{00B7} " ++
            Wrap.key("Alt+Shift+S") ++ " auto \u{00B7} " ++
            Wrap.key("Alt+M") ++ " model \u{00B7} " ++
            Wrap.key("Alt+H") ++ " help \u{00B7} " ++
            Wrap.key("Esc") ++ " cancel";
        const dialog_idle_hint = Wrap.icon("\u{1F916}") ++ " DIALOG mode \u{00B7} type prompt + Enter \u{00B7} " ++
            Wrap.key("Esc") ++ " / " ++ Wrap.key("Ctrl+Shift+X") ++ " to exit";
        const dialog_inflight_hint = Wrap.icon("\u{1F916}") ++ " DIALOG \u{00B7} " ++
            Wrap.icon("\u{1F9E0}") ++ " thinking\u{2026} \u{00B7} " ++
            Wrap.key("Esc") ++ " / " ++ Wrap.key("Ctrl+Shift+X") ++ " to exit";
        const auto_idle_hint = Wrap.icon("\u{26A1}") ++ " AUTO mode \u{00B7} type prompt + Enter \u{00B7} " ++
            Wrap.key("Esc") ++ " / " ++ Wrap.key("Ctrl+Shift+X") ++ " to exit";
        const auto_inflight_hint = Wrap.icon("\u{26A1}") ++ " AUTO \u{00B7} " ++
            Wrap.icon("\u{1F9E0}") ++ " thinking\u{2026} \u{00B7} " ++
            Wrap.key("Esc") ++ " / " ++ Wrap.key("Ctrl+Shift+X") ++ " to exit";
        const thinking_hint = Wrap.icon("\u{1F9E0}") ++ " thinking\u{2026}";

        pub fn statusText(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            // Persistent dialog/auto mode segment takes precedence
            // over the transient "thinking…" indicator — the user
            // wants to know they're IN a mode persistently across
            // the entire interaction, more than they want
            // per-request "thinking" feedback. We still show the
            // thinking glyph as a suffix on the mode segment when
            // a request is in flight.
            switch (rt.dialog_persistent_mode) {
                .off => {},
                .dialog => return if (rt.in_flight) dialog_inflight_hint else dialog_idle_hint,
                .auto => return if (rt.in_flight) auto_inflight_hint else auto_idle_hint,
            }

            if (rt.in_flight) return thinking_hint;

            // AI mode hint: when the line starts with the prefix,
            // surface the action keys so users discover the new
            // workflow. Takes precedence over the older single-
            // glyph `prefix_signal_status_text` indicator so the
            // hint string is what shows once the user has typed
            // `#: `.
            //
            // Esc and Ctrl+Shift+X both fire `llm_exec_cancel`.
            // Esc is the discoverable short form; Ctrl+Shift+X is
            // the safety lever for users on terminals that bind
            // Esc to something else, or who'd rather not have a
            // bare Esc grabbed inside AI mode.
            if (rt.ai_mode_active) {
                // With a configured `models[]` list, surface the
                // current pick inline so `Alt+M` cycling has
                // immediate visible feedback in the statusbar
                // (not just a transient latched hint). When the
                // user has only the legacy `cfg.model` (no list),
                // the static hint is fine — no point baking the
                // single name into the bar.
                if (cfg.models.len > 0) {
                    const pick = cfg.models[rt.current_model_idx];
                    // Same shape as ai_idle_hint but with the
                    // current model name interpolated after `Alt+M`.
                    // Fallback drops to the static hint if the
                    // model name overruns status_buf.
                    return std.fmt.bufPrint(
                        &rt.status_buf,
                        "{s} AI \u{00B7} {s} single \u{00B7} {s} dialog \u{00B7} {s} auto \u{00B7} {s} {s} \u{00B7} {s} help \u{00B7} {s} cancel",
                        .{
                            Wrap.icon("\u{2728}"),
                            Wrap.key("Alt+A"),
                            Wrap.key("Alt+S"),
                            Wrap.key("Alt+Shift+S"),
                            Wrap.key("Alt+M"),
                            pick,
                            Wrap.key("Alt+H"),
                            Wrap.key("Esc"),
                        },
                    ) catch ai_idle_hint;
                }
                return ai_idle_hint;
            }

            // Legacy prefix signal — kept for users who set the
            // older `prefix_signal_status_text` to something custom
            // and don't want the verbose AI hint. Reachable only
            // when `ai_mode_active` is false (above branch took
            // precedence), which today is the same condition as
            // "prefix not matched" since the flag is wired to the
            // same check. Keeping the code path so a future change
            // (e.g. a config knob to suppress the verbose hint)
            // doesn't break custom users.
            if (cfg.prefix_signal_status) {
                const line = ctx.line.current();
                if (std.mem.startsWith(u8, line, cfg.prefix)) {
                    return cfg.prefix_signal_status_text;
                }
            }
            return null;
        }

        // Pre-built OSC escape strings; comptime-baked from the
        // configured colour so we don't allocate per tick.
        const cursor_set_seq = "\x1B]12;" ++ cfg.prefix_signal_cursor_color ++ "\x07";
        const cursor_reset_seq = "\x1B]112\x07";

        /// Bytes to write to the user's outer terminal (NOT the
        /// pty.master, which goes to the shell). Used here for OSC
        /// 12 / 112 cursor-colour transitions while the user is
        /// typing a prefix-matched prompt. One-shot per transition
        /// — we only emit on edges so the terminal doesn't see
        /// redundant OSC traffic on every tick.
        /// Render the chat overlay's open or close sequence into
        /// `rt.chat_overlay_buf`. Returns false when the content
        /// overflows the buffer (caller should not emit a partial
        /// sequence — better to skip the paint than leave an
        /// incomplete alt-screen state on the terminal).
        ///
        /// Phase 2a renders the existing turn history as text-only
        /// content above a single-line "Alt+C close" footer. No
        /// chrome / no input row — those arrive in 2b/2c.
        fn paintChatOverlay(rt: *Runtime) bool {
            var w: std.Io.Writer = .fixed(&rt.chat_overlay_buf);
            if (!rt.chat_overlay_open) {
                // Close: leave the alt screen, restoring the
                // underlying shell screen unchanged. No further
                // bytes after the exit sequence — the shell's own
                // next render will populate whatever cursor
                // position it had before atty's overlay opened.
                w.writeAll("\x1B[?1049l") catch return false;
                rt.chat_overlay_buf_len = w.end;
                return true;
            }
            // Open: enter alt screen, clear, home cursor.
            w.writeAll("\x1B[?1049h\x1B[2J\x1B[1;1H") catch return false;
            // Title bar — dim chrome so it reads as frame, not content.
            // Coloured icon picks up the same fg=141 used in the
            // statusbar AI hint (consistent visual vocabulary).
            w.writeAll("\x1B[2m\x1B[22;38;5;141m\u{2728}\x1B[39;2m atty chat \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\x1B[0m\r\n\r\n") catch return false;

            const has_turns = rt.turns_len > 0;
            const has_conclusion = rt.conclusion_len > 0;
            if (!has_turns and !has_conclusion) {
                w.writeAll("  \x1B[2m(no conversation yet \u{2014} start one with Alt+S)\x1B[0m\r\n") catch return false;
            } else {
                for (rt.turns[0..rt.turns_len]) |turn| {
                    const prefix: []const u8 = switch (turn.kind) {
                        .user => "\x1B[22;1;38;5;14mYou:\x1B[0m ",
                        .assistant_exec => "\x1B[22;38;5;141matty:\x1B[0m ",
                        .observation => "\x1B[2mOutput:\x1B[0m ",
                    };
                    w.writeAll(prefix) catch return false;
                    // Bound turn content rendered to ~512 chars so a
                    // single huge JSON envelope doesn't blow the
                    // overlay buffer. Real chat UX in 2b/2c can do
                    // word-wrapping + structured assistant-turn
                    // rendering (parsed action / description).
                    const slice = if (turn.content.len > 512) turn.content[0..512] else turn.content;
                    w.writeAll(slice) catch return false;
                    if (turn.content.len > 512) {
                        w.writeAll(" \x1B[2m[\u{2026}truncated]\x1B[0m") catch return false;
                    }
                    w.writeAll("\r\n\r\n") catch return false;
                }
                if (has_conclusion and !has_turns) {
                    // Fallback: when the dialog already wrapped up
                    // (turns wiped on dialogReset) but the
                    // conclusion banner survived, surface it as the
                    // overlay's content. Rare path but defends
                    // against the empty-overlay-after-action=done
                    // case.
                    w.writeAll(rt.conclusion_buf[0..rt.conclusion_len]) catch return false;
                    w.writeAll("\r\n") catch return false;
                }
            }

            // Footer hint anchored at the bottom of the alt screen.
            // `\x1B[999;1H` parks the cursor at the largest plausible
            // row (terminals clamp to actual rows), then `\x1B[1A`
            // backs up one row so the hint sits on the bottom-but-one
            // line — leaves the last row free of overlay text in
            // case the terminal renders a scrollbar / status hint
            // there.
            w.writeAll("\x1B[999;1H\x1B[1A\x1B[2m[Alt+C close]\x1B[0m") catch return false;
            rt.chat_overlay_buf_len = w.end;
            return true;
        }

        pub fn provideTermBytes(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            // Chat overlay paint (phase 2a) takes precedence over
            // the conclusion + cursor-colour paths. The overlay's
            // alt-screen lives at the outer terminal, while
            // conclusion is for scroll-history and cursor-colour is
            // for the prompt area — they're mutually exclusive
            // surfaces.
            if (rt.chat_overlay_paint_pending) {
                rt.chat_overlay_paint_pending = false;
                if (paintChatOverlay(rt)) {
                    return rt.chat_overlay_buf[0..rt.chat_overlay_buf_len];
                }
                // Paint overran the buffer. The close path can't
                // overflow (single `?1049l` byte sequence), so this
                // only fires on open. Roll back `chat_overlay_open`
                // so the input swallow releases — otherwise the
                // user would see a frozen shell that eats every
                // keystroke until they remember to press Alt+C
                // again. Surface a hint so the failure mode isn't
                // silent.
                if (rt.chat_overlay_open) {
                    rt.chat_overlay_open = false;
                    latchErr(rt, "chat overlay too big to render — buffer overflow");
                    // Stderr fallback — the statusbar error surface
                    // is gated on `config.statusbar.enabled`, which
                    // defaults to false. Without this the user
                    // sees Alt+C do nothing with no diagnostic.
                    const overflow_msg = "atty: chat overlay too big to render — buffer overflow\n";
                    _ = std.c.write(2, overflow_msg, overflow_msg.len);
                }
            }
            // Conclusion banner emission takes precedence over the
            // cursor-colour edge logic — the banner is one-shot
            // multi-line output that scrolls into shell history;
            // cursor-colour OSC sequences are infinitely retriable
            // on the next tick. Drains the latch (one-shot
            // semantics).
            if (rt.conclusion_pending and rt.conclusion_len > 0) {
                rt.conclusion_pending = false;
                return rt.conclusion_buf[0..rt.conclusion_len];
            }
            if (!cfg.prefix_signal_cursor) return null;
            // Cursor colour fires when EITHER the prefix is matched
            // (user typing `#: …`) OR persistent dialog/auto mode
            // is active. The latter makes the colour stick across
            // the whole multi-step interaction — useful visual
            // confirmation that you're "talking to the LLM" even
            // when the line content doesn't have the prefix
            // (e.g. while reviewing an LLM-injected command).
            const line = ctx.line.current();
            const matches = std.mem.startsWith(u8, line, cfg.prefix) or rt.dialog_persistent_mode != .off;
            if (matches and !rt.cursor_signal_active) {
                rt.cursor_signal_active = true;
                return cursor_set_seq;
            }
            if (!matches and rt.cursor_signal_active) {
                rt.cursor_signal_active = false;
                return cursor_reset_seq;
            }
            return null;
        }

        // Dialog request body composition + parsed-response decoding
        // live in `llm/dialog.zig`. Re-exported here for callers that
        // expect the names on the `configure()` factory; the pub
        // re-exports also let test code reach them via the existing
        // surface without an import dance.
        pub const buildDialogRequestBody = dialog.buildRequestBody;
        pub fn parseDialogResponse(
            allocator: std.mem.Allocator,
            raw: []const u8,
            out: *DialogResponse,
        ) !void {
            return dialog.parseResponse(DialogResponse, allocator, raw, out);
        }

        // ---- worker + HTTP RPC + extract helpers -------------------------
        //
        // Worker thread fn, doRequest, doDialogRequest, RequestResult,
        // writeStatic, buildRequestBody, extractCommand, extractResponse,
        // extractRawContent, ExtractedResponse all live in
        // `llm/worker.zig` now (factory-bound to `cfg`). Re-exports
        // below keep the existing `pub` surface on the configure()
        // factory stable so tests + downstream callers (the `attach`
        // site's `Thread.spawn(.{}, worker, …)` etc.) don't need
        // updating.
        pub const RequestResult = worker_mod.RequestResult;
        pub const ExtractedResponse = worker_mod.ExtractedResponse;
        pub const buildRequestBody = worker_mod.buildRequestBody;
        pub const extractCommand = worker_mod.extractCommand;
        pub const extractResponse = worker_mod.extractResponse;
        pub const extractRawContent = worker_mod.extractRawContent;
        const writeStatic = worker_mod.writeStatic;
        const doRequest = worker_mod.doRequest;
        const doDialogRequest = worker_mod.doDialogRequest;
        const worker = worker_mod.worker;

        // Pure response/sanitization helpers extracted to
        // `llm/parse.zig` — see there for security rationale and
        // tests.
        pub const decodeContent = parse.decodeContent;
        pub const sanitizeExplanation = parse.sanitizeExplanation;
        pub const stripControlBytes = parse.stripControlBytes;
        pub const sanitizeCommand = parse.sanitizeCommand;
    };
}

// ===========================================================================
// Tests
// ===========================================================================

const testing = std.testing;
const test_io: std.Io = std.Io.failing;

// Pull in sibling parse-tests so `unit_tests.zig`'s single
// `_ = @import("modules/llm.zig")` line discovers them.
test {
    _ = parse;
}

test "configure exposes the expected hooks" {
    const L = configure(.{});
    try testing.expect(@hasDecl(L, "onInput"));
    try testing.expect(@hasDecl(L, "pollShellInput"));
    try testing.expect(@hasDecl(L, "statusText"));
    try testing.expectEqualStrings("llm", L.name);
}

test "buildRequestBody produces well-formed OpenAI chat-completion JSON" {
    const L = configure(.{ .model = "test-model" });
    const body = try L.buildRequestBody(testing.allocator, "test-model", "be terse", "bash", "", "list zig files");
    defer testing.allocator.free(body);

    try testing.expect(std.mem.indexOf(u8, body, "\"model\":\"test-model\"") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\"role\":\"system\"") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\"role\":\"user\"") != null);
    try testing.expect(std.mem.indexOf(u8, body, "be terse") != null);
    try testing.expect(std.mem.indexOf(u8, body, "Generate a bash command to: list zig files") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\"stream\":false") != null);
    // No raw newlines in the JSON — system prompt may have them
    // and they must be escaped to \n.
    for (body) |c| try testing.expect(c != '\n');
}

test "buildRequestBody escapes user content correctly (quotes + backslashes)" {
    const L = configure(.{});
    const body = try L.buildRequestBody(
        testing.allocator,
        "m",
        "sys",
        "bash",
        "",
        "echo \"hello\\world\"",
    );
    defer testing.allocator.free(body);
    try testing.expect(std.mem.indexOf(u8, body, "\\\"hello") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\\\\world") != null);
}

test "buildRequestBody appends a context blob when provided" {
    const L = configure(.{});
    const body = try L.buildRequestBody(
        testing.allocator,
        "m",
        "sys",
        "bash",
        "PATH_BASE=/opt/foo, PROJECT=acme",
        "list files",
    );
    defer testing.allocator.free(body);
    // The user message should now include "Context: …" after the
    // task; the literal commas + paths must survive JSON encoding
    // (commas are not escaped — `/` may be encoded as `\/` but
    // we expect it bare since we don't request slash escapes).
    try testing.expect(std.mem.indexOf(u8, body, "Generate a bash command to: list files") != null);
    try testing.expect(std.mem.indexOf(u8, body, "Context: PATH_BASE=/opt/foo, PROJECT=acme") != null);
}

test "buildRequestBody omits the context section entirely when blob is empty" {
    const L = configure(.{});
    const body = try L.buildRequestBody(
        testing.allocator,
        "m",
        "sys",
        "bash",
        "",
        "list files",
    );
    defer testing.allocator.free(body);
    try testing.expect(std.mem.indexOf(u8, body, "Context:") == null);
}

test "extractCommand pulls choices[0].message.content out of a chat response" {
    const L = configure(.{});
    var out: [64]u8 = undefined;
    const sample =
        \\{"id":"x","choices":[{"index":0,"message":{"role":"assistant","content":"ls *.zig"}}]}
    ;
    const n = L.extractCommand(sample, &out);
    try testing.expectEqualStrings("ls *.zig", out[0..n]);
}

test "extractCommand strips ```bash code fences" {
    const L = configure(.{});
    var out: [128]u8 = undefined;
    const sample =
        "{\"choices\":[{\"message\":{\"content\":\"```bash\\nls -la\\n```\"}}]}";
    const n = L.extractCommand(sample, &out);
    try testing.expectEqualStrings("ls -la", out[0..n]);
}

test "extractCommand decodes the common JSON escapes" {
    const L = configure(.{});
    var out: [128]u8 = undefined;
    const sample = "{\"choices\":[{\"message\":{\"content\":\"echo \\\"hi\\\"\"}}]}";
    const n = L.extractCommand(sample, &out);
    try testing.expectEqualStrings("echo \"hi\"", out[0..n]);
}

test "extractCommand skips uncommon escapes (\\b, \\f) without leaking the escape code char" {
    const L = configure(.{});
    var out: [128]u8 = undefined;
    // `\b` (backspace): both \ and b must be skipped, output is "ab" not "abb".
    const sample_b = "{\"choices\":[{\"message\":{\"content\":\"a\\bb\"}}]}";
    try testing.expectEqualStrings("ab", out[0..L.extractCommand(sample_b, &out)]);
    // `\f` (form feed): both \ and f must be skipped.
    const sample_f = "{\"choices\":[{\"message\":{\"content\":\"a\\fb\"}}]}";
    try testing.expectEqualStrings("ab", out[0..L.extractCommand(sample_f, &out)]);
}

test "extractCommand skips \\uXXXX unicode escapes cleanly" {
    const L = configure(.{});
    var out: [128]u8 = undefined;
    // Valid \u0020: skipped entirely (not decoded to a space), "ls-la" not "lsu0020-la".
    const sample_valid = "{\"choices\":[{\"message\":{\"content\":\"ls\\u0020-la\"}}]}";
    try testing.expectEqualStrings("ls-la", out[0..L.extractCommand(sample_valid, &out)]);
    // Malformed \u with only 2 hex digits before the closing quote: must not
    // skip past the closing " and extract garbage from the surrounding JSON.
    const sample_malformed = "{\"choices\":[{\"message\":{\"content\":\"ls\\u01\"}}]}";
    try testing.expectEqualStrings("ls", out[0..L.extractCommand(sample_malformed, &out)]);
}

